(function() {
  'use strict';

  // 配置常量
  const CLAIM_THRESHOLD = 2.0; // 文献声称的流行歌曲上限
  const DEFAULT_THRESHOLD = 2.0;

  // 工具函数：获取安全数值
  function getSafeNumber(val, defaultVal) {
    const num = Number(val);
    return isNaN(num) ? defaultVal : num;
  }

  // 初始化
  function init() {
    const slider = document.getElementById('fk-threshold');
    const thresholdValDisplay = document.getElementById('threshold-val');
    const bbResult = document.querySelector('.bb-result .status');
    const msdResult = document.querySelector('.msd-result .status');
    const resetBtn = document.getElementById('reset-viz');

    // 绑定来源按钮事件 (由内核处理，此处仅确保不报错)
    const sourceBtns = document.querySelectorAll('.source-btn');
    sourceBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        // 宿主内核会拦截 data-source 属性，此处不做 preventDefault 以免干扰内核
        // 仅做视觉反馈
        btn.style.borderColor = 'var(--accent)';
        setTimeout(() => {
          btn.style.borderColor = '';
        }, 300);
      });
    });

    // 更新逻辑
    function updateVisualization() {
      if (!slider) return;

      const currentThreshold = getSafeNumber(slider.value, DEFAULT_THRESHOLD);
      thresholdValDisplay.textContent = currentThreshold;

      // 逻辑判断：基于文献结论 (BB < 2, MSD > 2)
      // 如果用户设定的门槛 > 2，则 BB 通过 (因为 BB 始终 < 2)
      // 如果用户设定的门槛 < 2，则 BB 可能部分通过，但文献声称"始终<2"，故在 2 以下均为安全区
      // 为简化演示文献结论：只要门槛 >= 2，BB 即完全符合；MSD 因"显著更高"，在低门槛下不符合

      // BB 逻辑：文献称始终 < 2。若门槛 >= 2，则 Pass。
      const bbPass = currentThreshold >= CLAIM_THRESHOLD;

      // MSD 逻辑：文献称显著高于流行歌曲 (即 > 2)。若门槛 <= 2，则 Fail。
      // 只有当门槛设得很高 (例如 > 5) 时，MSD 才可能 Pass，但此处主要展示 2 的鸿沟
      const msdPass = currentThreshold > 4; // 假设非流行歌曲平均在 4-5 以上，此处仅为演示"难读"

      // 更新 UI
      if (bbPass) {
        bbResult.textContent = "符合标准 (易读)";
        bbResult.className = "status pass";
      } else {
        bbResult.textContent = "超出预期 (罕见)";
        bbResult.className = "status fail";
      }

      if (msdPass) {
        msdResult.textContent = "符合标准";
        msdResult.className = "status pass";
      } else {
        msdResult.textContent = "超出标准 (难读)";
        msdResult.className = "status fail";
      }
    }

    // 复位逻辑
    function resetVisualization() {
      if (slider) {
        slider.value = DEFAULT_THRESHOLD;
        updateVisualization();
      }
    }

    // 事件监听
    if (slider) {
      slider.addEventListener('input', updateVisualization);
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', resetVisualization);
    }

    // 初始运行
    updateVisualization();
  }

  // 等待 DOM 就绪
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
